class Solution {
public:
    int minMovesToSeat(vector<int>& seats, vector<int>& students) {
        int seat_count[101] = {0};
        int student_count[101] = {0};
        for (int x : seats) seat_count[x]++;
        for (int x : students) student_count[x]++;

        int ans = 0;
        int i = 1, j = 1;
        while (i <= 100 && j <= 100) {
            while (i <= 100 && seat_count[i] == 0) i++;
            while (j <= 100 && student_count[j] == 0) j++;
            if (i <= 100 && j <= 100) {
                ans += abs(i - j);
                seat_count[i]--;
                student_count[j]--;
            }
        }
        return ans;
    }
};
